INSERT INTO `edu_chn_word_question`
(`id`, `sense_id`, `question_type`, `stem`, `options_json`, `status`, `is_del`)
VALUES
(1, 2, 1, '下列对例句“顺风而呼，声非加疾也，而闻者彰。”中“疾”的解释，正确的一项是', '[{"content":"<形>劲疾，强劲，猛烈","correct":true},{"content":"<名>疾病","correct":false},{"content":"<动>憎恨","correct":false},{"content":"<形>快；迅速","correct":false}]', 1, 0),
(2, 2, 2, '下列句子中“疾”的意义和用法，与例句相同的一项是', '[{"content":"钟大而短，则其声<b>疾</b>而短闻。","correct":true},{"content":"屈平<b>疾</b>王听之不聪也。","correct":false}]', 1, 0),
(3, 3, 1, '下列对例句“顺风而呼，声非加疾也，而闻者彰。”中“彰”的解释，正确的一项是', '[{"content":"<形>明显，清楚","correct":true},{"content":"<动>表明","correct":false},{"content":"<名>表彰","correct":false},{"content":"<动>显示，揭露","correct":false}]', 1, 0),
(4, 3, 2, '下列句子中“彰”的意义和用法，与例句相同的一项是', '[{"content":"赖明君子信义昭<b>彰</b>，至达远冤。","correct":true},{"content":"若无兴德之言，则责攸之、祎、允等之慢，以<b>彰</b>其咎。","correct":false}]', 1, 0),
(5, 4, 1, '下列对例句“假舆马者，非利足也，而致千里；”中“假”的解释，正确的一项是', '[{"content":"<动>借助，利用","correct":true},{"content":"<形>虚假","correct":false},{"content":"<动>给予、授予","correct":false},{"content":"<连>如果","correct":false}]', 1, 0),
(6, 4, 2, '下列句子中“假”的意义和用法，与例句相同的一项是', '[{"content":"君子生非异也，善<b>假</b>于物也。","correct":true},{"content":"乃悟前狼<b>假</b>寐，盖以诱敌。","correct":false}]', 1, 0),
(7, 5, 1, '下列对例句“假舟楫者，非能水也，而绝江河。”中“绝”的解释，正确的一项是', '[{"content":"<动>横渡","correct":true},{"content":"<动>断，断绝","correct":false},{"content":"<动>隔绝，隔断","correct":false},{"content":"<形>到极点的，独一无二的","correct":false}]', 1, 0),
(8, 5, 2, '下列句子中“绝”的意义和用法，与例句相同的一项是', '[{"content":"横<b>绝</b>四海。","correct":true},{"content":"楚诚能<b>绝</b>齐，秦愿献商於之地六百里。","correct":false}]', 1, 0),
(9, 6, 1, '下列对例句“积土成山，风雨兴焉；”中“积”的解释，正确的一项是', '[{"content":"<动>堆积，积累","correct":true},{"content":"<名>积累的东西","correct":false},{"content":"<动>聚集","correct":false},{"content":"<形>堆积或积累起来的。","correct":false}]', 1, 0),
(10, 6, 2, '下列句子中“积”的意义和用法，与例句相同的一项是', '[{"content":"<b>积</b>水成渊，蛟龙生焉。","correct":true},{"content":"为国者无使为<b>积</b>威之所劫哉。","correct":false}]', 1, 0),
(13, 8, 1, '下列对例句“驽马十驾，功在不舍。”中“舍”的解释，正确的一项是', '[{"content":"<动>舍弃，放弃","correct":true},{"content":"<动>放开，释放","correct":false},{"content":"<名>房舍，住房","correct":false},{"content":"<动>施舍，布施","correct":false}]', 1, 0),
(14, 8, 2, '下列句子中“舍”的意义和用法，与例句相同的一项是', '[{"content":"<b>舍</b>生而取义者也。","correct":true},{"content":"土地平旷，屋<b>舍</b>俨然，有良田、美池、桑竹之属。","correct":false}]', 1, 0),
(15, 9, 1, '下列对例句“积土成山，风雨兴焉；”中“兴”的解释，正确的一项是', '[{"content":"<动>兴起","correct":true},{"content":"<动>兴办","correct":false},{"content":"<名>兴致","correct":false},{"content":"<形>兴盛","correct":false}]', 1, 0),
(16, 9, 2, '下列句子中“兴”的意义和用法，与例句相同的一项是', '[{"content":"清风徐来，水波不<b>兴</b>。","correct":true},{"content":"政通人和，百废俱<b>兴</b>。","correct":false}]', 1, 0),
(17, 10, 1, '下列对例句“吾尝跂而望矣，不如登高之博见也。”中“望”的解释，正确的一项是', '[{"content":"<动>远看，远望","correct":true},{"content":"<名>农历每月十五日","correct":false},{"content":"<动>盼望；希望；期望","correct":false},{"content":"<名>名望；声望","correct":false}]', 1, 0),
(18, 10, 2, '下列句子中“望”的意义和用法，与例句相同的一项是', '[{"content":"<b>望</b>晚日照城郭，汶水、徂徕如画，而半山居雾若带然。","correct":true},{"content":"壬戌之秋，七月既<b>望</b>，苏子与客泛舟游于赤壁之下。","correct":false}]', 1, 0),
(19, 11, 1, '下列对例句“故木受绳则直，金就砺则利，君子博学而日参省乎己，则知明而行无过矣。”中“知”的解释，正确的一项是', '[{"content":"<通假>同“智”，智慧，聪明","correct":true},{"content":"<动>知道；了解","correct":false},{"content":"<动>感到；觉得","correct":false},{"content":"<名>知觉；感觉","correct":false}]', 1, 0),
(20, 11, 2, '下列句子中“知”的意义和用法，与例句相同的一项是', '[{"content":"失其所与，不<b>知</b>。","correct":true},{"content":"夜缒而出，见秦伯，曰：“秦、晋围郑，郑既<b>知</b>亡矣。","correct":false}]', 1, 0),
(21, 12, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“而”的解释，正确的一项是', '[{"content":"<连>表转折","correct":true},{"content":"<连>表承接","correct":false},{"content":"<连>表因果","correct":false},{"content":"<连>表并列","correct":false}]', 1, 0),
(22, 12, 2, '下列句子中“而”的意义和用法，与例句相同的一项是', '[{"content":"浩浩乎如冯虚御风，<b>而</b>不知其所止；","correct":true},{"content":"吾见师出，<b>而</b>不见其入也。","correct":false}]', 1, 0),
(23, 13, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“于”的解释，正确的一项是', '[{"content":"<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等","correct":true},{"content":"<介>介绍比较的对象，可译为“比”","correct":false},{"content":"<介>介绍动作行为涉及的对象，可译为“对”、“向”等","correct":false},{"content":"<介>介绍动作行为的主动者，可译为“被”","correct":false}]', 1, 0),
(24, 13, 2, '下列句子中“于”的意义和用法，与例句相同的一项是', '[{"content":"壬戌之秋，七月既望，苏子与客泛舟游<b>于</b>赤壁之下。","correct":true},{"content":"吾师道也，夫庸知其年之先后生<b>于</b>吾乎？","correct":false}]', 1, 0),
(25, 14, 1, '下列对例句“青，取之于蓝，而青于蓝；”中“之”的解释，正确的一项是', '[{"content":"<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等","correct":true},{"content":"<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”","correct":false},{"content":"<代>指示代词，相当于“这个”、“这”、“这种”等","correct":false},{"content":"<助>用在主谓之间，取消句子独立性，一般不必译出","correct":false}]', 1, 0),
(26, 14, 2, '下列句子中“之”的意义和用法，与例句相同的一项是', '[{"content":"秦时与臣游，项伯杀人，臣活<b>之</b>。","correct":true},{"content":"古<b>之</b>学者必有师。","correct":false}]', 1, 0),
(27, 15, 1, '下列对例句“虽有槁暴，不复挺者，輮使之然也。”中“者”的解释，正确的一项是', '[{"content":"<助>用在因果复句或条件复句偏句的末尾，提示原因或条件","correct":true},{"content":"<代>用在数词后面，往往总指上文所提到的人、事、物。翻译时在人、事、物名称前加“个”、“件”、“种”等","correct":false},{"content":"<助>用动词、形容词和动词性词组、形容词性词组的后面，组成一个名词性结构，相当于“……的人（人、事、情况等）”","correct":false},{"content":"<助>用某些比况、描写的词语后面，相当于“……的样子”","correct":false}]', 1, 0),
(28, 15, 2, '下列句子中“者”的意义和用法，与例句相同的一项是', '[{"content":"吾妻之美我<b>者</b>，私我也。","correct":true},{"content":"范增数目项王，举所佩玉玦以示之<b>者</b>三。","correct":false}]', 1, 0),
(29, 16, 1, '下列对例句“虽有槁暴，不复挺者，輮使之然也。”中“也”的解释，正确的一项是', '[{"content":"<语助>用于句末；表示陈述或解释","correct":true},{"content":"<语助>用于句末；表判断","correct":false},{"content":"<语助>用于句末；表感叹","correct":false},{"content":"<语助>用于句末；表疑问或反问","correct":false}]', 1, 0),
(30, 16, 2, '下列句子中“也”的意义和用法，与例句相同的一项是', '[{"content":"愿伯具言臣之不敢倍德<b>也</b>。","correct":true},{"content":"张良曰：“沛公之参乘樊哙者<b>也</b>”。","correct":false}]', 1, 0),
(31, 17, 1, '下列对例句“古之学者必有师。”中“师”的解释，正确的一项是', '[{"content":"<名>老师","correct":true},{"content":"<意动>以……为师，意动用法","correct":false},{"content":"<动>学习","correct":false},{"content":"<名>军队","correct":false}]', 1, 0),
(32, 17, 2, '下列句子中“师”的意义和用法，与例句相同的一项是', '[{"content":"<b>师</b>者，所以传道受业解惑也。","correct":true},{"content":"加之以<b>师</b>旅，因之以饥馑。","correct":false}]', 1, 0),
(33, 18, 1, '下列对例句“人非生而知之者，孰能无惑？”中“惑”的解释，正确的一项是', '[{"content":"<名>疑惑，疑难问题","correct":true},{"content":"<动>迷惑","correct":false},{"content":"<形>疑惑的","correct":false},{"content":"<动>使……迷惑","correct":false}]', 1, 0),
(34, 18, 2, '下列句子中“惑”的意义和用法，与例句相同的一项是', '[{"content":"欲人之无<b>惑</b>也难矣！","correct":true},{"content":"于其身也，则耻师焉，<b>惑</b>矣。","correct":false}]', 1, 0),
(37, 20, 1, '下列对例句“惑而不从师，其为惑也，终不解矣。”中“从”的解释，正确的一项是', '[{"content":"<动>跟随，跟从","correct":true},{"content":"<动>参与","correct":false},{"content":"<介>从，由","correct":false},{"content":"<动>顺从，听从","correct":false}]', 1, 0),
(38, 20, 2, '下列句子中“从”的意义和用法，与例句相同的一项是', '[{"content":"一狼仍<b>从</b>。","correct":true},{"content":"择其善者而<b>从</b>之。","correct":false}]', 1, 0),
(41, 22, 1, '下列对例句“是故圣益圣，愚益愚。”中“益”的解释，正确的一项是', '[{"content":"<副>更加","correct":true},{"content":"<名>好处","correct":false},{"content":"<动>增加","correct":false},{"content":"<副>渐渐地","correct":false}]', 1, 0),
(42, 22, 2, '下列句子中“益”的意义和用法，与例句相同的一项是', '[{"content":"香远<b>益</b>清。","correct":true},{"content":"自以为大有所<b>益</b>。","correct":false}]', 1, 0),
(45, 26, 1, '下列对例句“古之学者必有师。”中“之”的解释，正确的一项是', '[{"content":"<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”","correct":true},{"content":"<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等","correct":false},{"content":"<代>指示代词，相当于“这个”、“这”、“这种”等","correct":false},{"content":"<助>用在主谓之间，取消句子独立性，一般不必译出","correct":false}]', 1, 0),
(46, 26, 2, '下列句子中“之”的意义和用法，与例句相同的一项是', '[{"content":"壬戌<b>之</b>秋，七月既望，苏子与客泛舟游于赤壁<b>之</b>下。","correct":true},{"content":"青，取<b>之</b>于蓝，而青于蓝；","correct":false}]', 1, 0),
(47, 27, 1, '下列对例句“惑而不从师，其为惑也，终不解矣。”中“其”的解释，正确的一项是', '[{"content":"<代>指示代词，相当于“那”、“那些”","correct":true},{"content":"<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”","correct":false},{"content":"<代>第三人称代词。相当于“他（她）”、“它”、“他们”","correct":false},{"content":"<代>指示代词，相当于“其中”、“当中”","correct":false}]', 1, 0),
(48, 27, 2, '下列句子中“其”的意义和用法，与例句相同的一项是', '[{"content":"<b>其</b>人曰：“天果积气，日月星宿不当坠邪？”","correct":true},{"content":"浩浩乎如冯虚御风，而不知<b>其</b>所止；","correct":false}]', 1, 0),
(51, 29, 1, '下列对例句“吾师道也，夫庸知其年之先后生于吾乎？”中“于”的解释，正确的一项是', '[{"content":"<介>介绍比较的对象，可译为“比”","correct":true},{"content":"<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等","correct":false},{"content":"<介>介绍动作行为涉及的对象，可译为“对”、“向”等","correct":false},{"content":"<介>介绍动作行为的主动者，可译为“被”","correct":false}]', 1, 0),
(52, 29, 2, '下列句子中“于”的意义和用法，与例句相同的一项是', '[{"content":"冰，水为之，而寒<b>于</b>水。","correct":true},{"content":"青，取之<b>于</b>蓝，而青<b>于</b>蓝。","correct":false}]', 1, 0),
(53, 30, 1, '下列对例句“生乎吾前，其闻道也固先乎吾，吾从而师之。”中“乎”的解释，正确的一项是', '[{"content":"<介>相当于“于”；介绍比较对象。译为“与”、“对”、“比”","correct":true},{"content":"<介>相当于“于”；介绍处所、方向、时间。译为“在”、“由”等","correct":false},{"content":"<助>用在句末，表示疑问或反问","correct":false},{"content":"<助>用在句末，表示感叹","correct":false}]', 1, 0),
(54, 30, 2, '下列句子中“乎”的意义和用法，与例句相同的一项是', '[{"content":"以吾一日长<b>乎</b>尔，毋吾以也。","correct":true},{"content":"浩浩<b>乎</b>如冯虚御风，而不知其所止；","correct":false}]', 1, 0),
(55, 31, 1, '下列对例句“师者，所以传道受业解惑也。”中“所”的解释，正确的一项是', '[{"content":"<助>“所以”：表示行为所凭借的方式、方法或依据","correct":true},{"content":"<名>处所；地方","correct":false},{"content":"<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等","correct":false},{"content":"<助>与“为”相呼应，构成“为……所……”的被动句式","correct":false}]', 1, 0),
(56, 31, 2, '下列句子中“所”的意义和用法，与例句相同的一项是', '[{"content":"此臣<b>所</b>以报先帝而忠陛下之职分也。","correct":true},{"content":"<b>所</b>以遣将守关者，备他盗之出入与非常也。","correct":false}]', 1, 0),
(57, 32, 1, '下列对例句“于其身也，则耻师焉，惑矣。”中“则”的解释，正确的一项是', '[{"content":"<连>表示转折，相当于“却”、“可是”","correct":true},{"content":"<连>表示顺承，相当于“就”、“便”","correct":false},{"content":"<连>表示假设，相当于“如果”、“假使”","correct":false},{"content":"<副>用于加强判断，相当于“乃”、“就是”","correct":false}]', 1, 0),
(58, 32, 2, '下列句子中“则”的意义和用法，与例句相同的一项是', '[{"content":"某<b>则</b>以为受命于人主，议法度而修之于朝廷，以授之于有司，不为侵官；","correct":true},{"content":"居<b>则</b>曰：‘不吾知也！","correct":false}]', 1, 0),
(59, 33, 1, '下列对例句“逝者如斯，而未尝往也；”中“逝”的解释，正确的一项是', '[{"content":"<动>去，往，流逝","correct":true},{"content":"<动>往，去","correct":false},{"content":"<动>死亡","correct":false},{"content":"<通假>通“誓”，发誓","correct":false}]', 1, 0),
(60, 33, 2, '下列句子中“逝”的意义和用法，与例句相同的一项是', '[{"content":"<b>逝</b>者如斯夫，不舍昼夜。","correct":true},{"content":"既痛<b>逝</b>者，并以为国人之读兹编勖。","correct":false}]', 1, 0),
(61, 34, 1, '下列对例句“盈虚者如彼，而卒莫消长也。”中“盈”的解释，正确的一项是', '[{"content":"<形>圆满","correct":true},{"content":"<形>满","correct":false},{"content":"<形>旺盛，充沛","correct":false},{"content":"<动>充满、充盈","correct":false}]', 1, 0),
(62, 34, 2, '下列句子中“盈”的意义和用法，与例句相同的一项是', '[{"content":"天地<b>盈</b>虚，与时消息。","correct":true},{"content":"彼竭我<b>盈</b>，故克之。","correct":false}]', 1, 0),
(63, 35, 1, '下列对例句“浩浩乎如冯虚御风，而不知其所止；”中“虚”的解释，正确的一项是', '[{"content":"<名>天空","correct":true},{"content":"<形>缺，不完整","correct":false},{"content":"<形>虚假","correct":false},{"content":"<副>徒然、白白地","correct":false}]', 1, 0),
(64, 35, 2, '下列句子中“虚”的意义和用法，与例句相同的一项是', '[{"content":"列子御风，泠然善也。","correct":true},{"content":"户庭无尘杂，<b>虚</b>室有余闲。","correct":false}]', 1, 0),
(67, 37, 1, '下列对例句“壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下。”中“望”的解释，正确的一项是', '[{"content":"<名>农历每月十五日","correct":true},{"content":"<动>远看，远望","correct":false},{"content":"<动>盼望；希望；期望","correct":false},{"content":"<名>名望；声望","correct":false}]', 1, 0),
(68, 37, 2, '下列句子中“望”的意义和用法，与例句相同的一项是', '[{"content":"<b>望</b>之前后，火明如昼。","correct":true},{"content":"先达德隆<b>望</b>尊，门人弟子填其室。","correct":false}]', 1, 0),
